export const st = (key, params = {}) => {
  let value = strings[key]?.[getLanguage() === 'pl' ? 1 : 0] ?? key;
  for (const [k, v] of Object.entries(params)) value = value.replaceAll('{' + k + '}', String(v));
  return value;
};
